
CREATE TABLE `dem_price` (
                             `id` int NOT NULL AUTO_INCREMENT,
                             `creator` int NOT NULL DEFAULT '0',
                             `numorders` varchar(32) DEFAULT NULL,
                             `id_customer` int NOT NULL DEFAULT '0' COMMENT 'id дилера',
                             `date_n` varchar(64) DEFAULT NULL,
                             `naim` text,
                             `napr` varchar(32) DEFAULT NULL,
                             `position` varchar(8) DEFAULT NULL,
                             `pos_int` int NOT NULL DEFAULT '0',
                             `pos_k` varchar(8) DEFAULT NULL,
                             `vendor` varchar(64) DEFAULT NULL,
                             `name_position` text NOT NULL,
                             `currency` varchar(8) NOT NULL DEFAULT '',
                             `kol_vo` double NOT NULL DEFAULT '0',
                             `kol_vo_sklad` double NOT NULL DEFAULT '0',
                             `price_position` double NOT NULL DEFAULT '0',
                             `price_wo_discount` double NOT NULL DEFAULT '0',
                             `discount` double NOT NULL DEFAULT '0',
                             `type_position` varchar(128) NOT NULL DEFAULT '',
                             `upak` varchar(20) NOT NULL DEFAULT '' COMMENT 'упаковка из поля индекс',
                             PRIMARY KEY (`id`),
                             KEY `numorders` (`numorders`),
                             KEY `position` (`position`),
                             KEY `name_position` (`name_position`(255)),
                             KEY `type_position` (`type_position`),
                             KEY `pos_k` (`pos_k`),
                             KEY `vendor` (`vendor`),
                             KEY `id_customer` (`id_customer`),
                             KEY `creator` (`creator`)
) ENGINE=MyISAM AUTO_INCREMENT=34 DEFAULT CHARSET=cp1251;

